export const BODY: string = "\n<p>بوابات التوظيف ونماذج التقديم صارمة مع الصور. تحدد حدًا أقصى للحجم وأبعادًا دقيقة وصيغًا مقبولة، وترفض كل ما يخالفها دون شرح.</p>\n<p>مئتا كيلوبايت هي الحد الأكثر شيوعًا للصور والمستندات في هذه الأنظمة. حجم كافٍ لصورة واضحة، وصغير بما يكفي لقواعد بيانات البوابة.</p>\n<p>يشرح هذا المقال كيف تجهّز صور 200 كيلوبايت تنجح في بوابات التوظيف والنماذج من أول مرة.</p>\n<h2 id=\"why-portals-use-200kb\">لماذا تحدد بوابات التوظيف الصور بـ200 كيلوبايت؟</h2>\n<p>بوابات التوظيف تخزّن ملايين الطلبات، لذلك تحدد حد 200 كيلوبايت للحفاظ على قواعد بياناتها سريعة وتكاليف التخزين منخفضة.</p>\n<p>الحد موحد أيضًا ليكون عادلًا. كل متقدم يرفع وزنًا مشابهًا، فلا يحصل أحد على ميزة من ملف أكبر أو أوضح.</p>\n<h2 id=\"profile-photo-rules\">قواعد صورة الملف الشخصي في بوابات التوظيف</h2>\n<p>قواعد صورة الملف الشخصي بسيطة عادة: وجه مواجه للأمام، وخلفية فاتحة بسيطة، وأبعاد مربعة مثل 600 في 600 بكسل.</p>\n<p>تجنب النظارات الشمسية والقبعات والخلفيات المزدحمة. الصورة النظيفة تُقبل أسرع وتترك انطباعًا احترافيًا لدى مسؤول التوظيف.</p>\n<h2 id=\"resume-documents\">السير الذاتية والشهادات ومسح المستندات</h2>\n<p>السير الذاتية والشهادات تُرفع غالبًا كصور أو ملفات PDF. امسحها بدقة 200 نقطة في البوصة واحفظها بصيغة JPG للوصول إلى 200 كيلوبايت بسهولة.</p>\n<p>إذا كان النص صغيرًا، فحافظ على الأبعاد كبيرة. النص يحتاج حدة، وتقليص الأبعاد بقوة يجعله غير مقروء.</p>\n<h2 id=\"signature-rules\">صور التوقيع للنماذج</h2>\n<p>صور التوقيع للنماذج سهلة الضغط لأنها معظمه مساحة بيضاء. امسح التوقيع بدقة معتدلة واحفظه بصيغة JPG.</p>\n<p>وقّع بقلم أسود على ورق أبيض نظيف. التوقيع الواضح يُضغط إلى أقل من 200 كيلوبايت دون أي جهد تقريبًا.</p>\n<h2 id=\"format-choice-portals\">كيف تختار الصيغة للبوابات؟</h2>\n<p>للبوابات، JPG هو الخيار الآمن دائمًا. تقبله كل الأنظمة القديمة والحديثة، ولا توجد بوابة ترفض JPG.</p>\n<p>تجنب WebP وPNG للصور الفوتوغرافية في البوابات. WebP قد يُرفض، وPNG كبير جدًا وقد يفشل في الوصول إلى الحد.</p>\n<h2 id=\"step-by-step-portal\">خطوة بخطوة: كيف تجهّز صورة بوابة؟</h2>\n<p>ابدأ بصورة عالية الجودة بخلفية بسيطة. قصّها إلى الأبعاد المطلوبة، ثم اضغطها باستخدام <a href=\"/ar/daght-as-sura-ila-200kb/\">ضاغط 200 كيلوبايت</a>.</p>\n<p>بعد الضغط، افتح الملف وتأكد من وضوح الوجه وصحة الأبعاد. إذا كان كل شيء صحيحًا، فارفعه إلى البوابة.</p>\n<h2 id=\"common-rejections\">أسباب الرفض الشائعة وحلولها</h2>\n<p>أكثر أسباب الرفض شيوعًا أن الأبعاد لا تطابق المطلوب. البوابة قد تطلب 600 في 600 بكسل وترفض أي أبعاد أخرى مهما كان الحجم صحيحًا.</p>\n<p>السبب الثاني أن الصيغة غير مقبولة. تحقق من قائمة الصيغ المقبولة في البوابة قبل الرفع، ولا تفترض أن كل الصيغ تعمل.</p>\n<h2 id=\"multiple-documents\">كيف تتعامل مع عدة مستندات دفعة واحدة؟</h2>\n<p>عند التقديم إلى عدة وظائف، جهّز كل المستندات مرة واحدة: الصورة والتوقيع والسيرة الذاتية والشهادات. احفظها في مجلد واحد باسم الطلب.</p>\n<p>سمِّ كل ملف بوضوح حسب الغرض. التنظيم المسبق يمنع رفع الملف الخاطئ عندما تكون تحت ضغط الموعد النهائي.</p>\n<h2 id=\"mobile-applications\">كيف تقدّم من الهاتف؟</h2>\n<p>التقديم من الهاتف ممكن بالكامل. افتح الأداة في متصفح هاتفك وارفع الصورة من معرضك، ثم اضغط ونزّل دون حاسوب.</p>\n<p>قبل الإرسال، افتح الملف المنزّل على هاتفك وتأكد من وضوحه. الشاشة الصغيرة قد تخفي مشاكل تظهر على شاشة أكبر.</p>\n<h2 id=\"after-submission\">بعد الإرسال: ماذا تحتفظ به؟</h2>\n<p>بعد الإرسال، احتفظ بنسخة من كل ملف رفعته. قد تحتاج الملف نفسه لبطاقة القبول أو لجولة مقابلة لاحقة.</p>\n<p>احتفظ أيضًا بلقطة شاشة لتأكيد الإرسال. إثبات التقديم مفيد إذا حدث خطأ في النظام أو طُلب منك إعادة الرفع.</p>\n<h2 id=\"beyond-200kb\">عندما تطلب البوابة حجمًا مختلفًا</h2>\n<p>إذا طلبت البوابة حدًا مختلفًا، فاستخدم <a href=\"/ar/daght-as-sura-ila-50kb/\">ضاغط 50 كيلوبايت</a> أو <a href=\"/ar/daght-as-sura-ila-100kb/\">ضاغط 100 كيلوبايت</a> للحدود الأصغر.</p>\n<p>وللحدود الأكبر، جرّب <a href=\"/ar/daght-as-sura-ila-500kb/\">ضاغط 500 كيلوبايت</a>.</p>\n<p>وللحدود غير المعتادة، استخدم <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a> الذي يصل إلى أي حجم تحدده بالضبط.</p>\n<h2 id=\"photo-day\">كيف تستعد في يوم الصورة؟</h2>\n<p>في يوم الصورة، التقطها قرب نافذة بإضاءة نهارية طبيعية. الإضاءة الجيدة تفعل للجودة أكثر من أي إعداد في الأداة.</p>\n<p>ارتدِ ملابس بلون موحد وقف أمام جدار فاتح فارغ. الخلفية البسيطة تُضغط أفضل وتترك الميزانية للوجه.</p>\n<h2 id=\"document-checklist\">قائمة تحقق للمستندات في الطلبات</h2>\n<p>قائمة مستندات الطلب: صورة شخصية، وتوقيع، وسيرة ذاتية، وشهادات، وهوية. جهّزها كلها قبل فتح النموذج، لا أثناءه.</p>\n<p>تحقق من كل ملف: الحجم أقل من الحد، والصيغة مقبولة، والأبعاد مطابقة. الفحص المسبق يمنع الأخطاء تحت الضغط.</p>\n<h2 id=\"deadline-pressure\">كيف تعمل تحت ضغط الموعد النهائي؟</h2>\n<p>تحت ضغط الموعد النهائي، يرتكب الناس أخطاء بسيطة: رفع الملف الخاطئ أو نسيان فحص الأبعاد. جهّز كل شيء قبل يوم الموعد النهائي.</p>\n<p>إذا تأخرت، فابدأ بالصورة أولًا لأنها تستغرق وقتًا أطول. المستندات النصية أسرع في التجهيز.</p>\n<h2 id=\"reusing-photos\">كيف تعيد استخدام صورة البوابة في عدة طلبات؟</h2>\n<p>الصورة الجيدة صالحة لعدة طلبات. إذا طابقت قواعد معظم البوابات، فاستخدم النسخة نفسها في كل مكان دون إعادة ضغط.</p>\n<p>لكن تحقق من أبعاد كل بوابة قبل إعادة الاستخدام. بوابة تطلب 600 في 600 قد تختلف عن بوابة تطلب 200 في 230.</p>\n<h2 id=\"verification-steps\">خطوات التحقق في البوابة</h2>\n<p>بعض البوابات تعرض معاينة لصورتك قبل الإرسال النهائي. استخدمها للتحقق من أن الوجه يظهر بالاتجاه الصحيح وأن الصورة لم تُقلب.</p>\n<p>إذا طلبت البوابة تأكيدًا بالبريد، فاحتفظ بالرسالة. إثبات التقديم مفيد إذا حدث خطأ في النظام أو طُلب منك إعادة الرفع.</p>\n<h2 id=\"long-term-habits\">عادات طويلة الأمد لصور الطلبات</h2>\n<p>احتفظ بصورة شخصية محدثة وجاهزة دائمًا. التقط صورة جديدة كل سنة أو سنتين، حتى لا تضطر إلى التجهيز تحت ضغط الموعد النهائي.</p>\n<p>خزّن نسخًا بأحجام مختلفة: 50 و100 و200 كيلوبايت. بهذا تكون جاهزًا لأي بوابة مهما كان حدها. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-daght-as-sura-ila-200kb/\">الدليل الكامل لضغط الصورة إلى 200 كيلوبايت</a> و<a href=\"/ar/blog/kayfiyya-daght-as-sura-ila-200kb/\">كيفية ضغط صورة إلى 200 كيلوبايت</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما أبعاد صورة الملف الشخصي في بوابة التوظيف؟","answer":"الأبعاد المربعة مثل 600 في 600 بكسل شائعة، لكن القاعدة تختلف من بوابة إلى أخرى. تحقق من صفحة التعليمات في البوابة نفسها قبل الرفع، والتزم بالأبعاد المطلوبة بدقة."},{"question":"هل يمكنني رفع صورة WebP إلى بوابة توظيف؟","answer":"يفضل تجنب WebP في البوابات. كثير من أنظمة التوظيف القديمة ترفضه. استخدم JPG دائمًا لصور البوابات، فهو مقبول في كل مكان دون استثناء تقريبًا."},{"question":"مسح شهادتي يبدو ضبابيًا بعد ضغطه إلى 200 كيلوبايت. ماذا حدث؟","answer":"غالبًا لأن النص فقد حدته أثناء الضغط. حافظ على الأبعاد كبيرة وخفض الجودة تدريجيًا بدل تقليص الأبعاد. وإذا استمرت المشكلة، جرّب PNG للنصوص الصغيرة."},{"question":"هل أحتاج إلى صورة احترافية لبوابة التوظيف؟","answer":"ليست ضرورية. صورة واضحة بخلفية بسيطة وإضاءة جيدة تكفي في معظم البوابات. الصورة الاحترافية تفيد، لكنها ليست شرطًا للقبول في النموذج."},{"question":"هل يمكنني استخدام الصورة المضغوطة نفسها في عدة بوابات؟","answer":"نعم، إذا طابقت الصورة قواعد كل بوابة. معظم البوابات تطلب الحجم والأبعاد والصيغة نفسها، فنسخة واحدة جيدة تعمل في عدة أماكن. تحقق فقط من الأبعاد المطلوبة في كل بوابة."},{"question":"لماذا ما زالت البوابة ترفض صورتي التي تزن 199 كيلوبايت؟","answer":"تحقق من الأبعاد والصيغة أولًا. بعض البوابات ترفض الملف بسبب الأبعاد لا الحجم، أو بسبب صيغة WebP. وإذا كان كل شيء صحيحًا، فأعد الضغط من الملف الأصلي بهدف 195 كيلوبايت."}];
